package com.project.app.app;

import com.project.app.model.StudentModel;
import com.project.app.service.StudentServiceLayer;

import java.util.Scanner;
import java.util.regex.Pattern;

public class MainApplication {

    // Name should contain letters and single/multiple words separated by spaces.
    private static final Pattern NAME_PATTERN = Pattern.compile("^[A-Za-z]+(?:\\s+[A-Za-z]+)*$");

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StudentServiceLayer service = new StudentServiceLayer();

        while (true) {
            System.out.println("\n===== Student Course Registration & Fee Management =====");
            System.out.println("1. Add Student");
            System.out.println("2. Register for Course");
            System.out.println("3. View All Students with Courses");
            System.out.println("4. Search Student by ID");
            System.out.println("5. Update Student");
            System.out.println("6. Update Course Fee");
            System.out.println("7. Cancel Registration");
            System.out.println("8. Delete Student");
            System.out.println("9. High Paying Students Report");
            System.out.println("10. Course-wise Student Count");
            System.out.println("11. Exit");
            System.out.print("Enter choice: ");

            int choice = readInt(scanner);

            switch (choice) {
                case 1:
                    System.out.print("Student ID: ");
                    int id1 = readInt(scanner);

                    System.out.print("Student Name: ");
                    String name1 = readValidName(scanner, "Student Name");

                    System.out.print("Student Age: ");
                    int age = readInt(scanner);

                    System.out.print("Student Branch: ");
                    String branch1 = readNonBlank(scanner, "Student Branch");

                    service.addNewStudent(new StudentModel(id1, name1, age, branch1));
                    break;

                case 2:
                    System.out.print("Student ID: ");
                    int id2 = readInt(scanner);

                    System.out.print("Course Name: ");
                    String course2 = readNonBlank(scanner, "Course Name");

                    System.out.print("Fees Paid: ");
                    double fee2 = readDouble(scanner);

                    service.registerStudentForCourse(id2, course2, fee2);
                    break;

                case 3:
                    service.viewAllStudentsWithRegistrations();
                    break;

                case 4:
                    System.out.print("Student ID: ");
                    service.searchStudentRegistrationById(readInt(scanner));
                    break;

                case 5:
                    System.out.print("Student ID: ");
                    int id5 = readInt(scanner);

                    System.out.print("New Name: ");
                    String name5 = readValidName(scanner, "New Name");

                    System.out.print("New Branch: ");
                    String branch5 = readNonBlank(scanner, "New Branch");

                    service.updateStudentDetails(id5, name5, branch5);
                    break;

                case 6:
                    System.out.print("Student ID: ");
                    int id6 = readInt(scanner);

                    System.out.print("Course Name: ");
                    String course6 = readNonBlank(scanner, "Course Name");

                    System.out.print("New Fee: ");
                    double fee6 = readDouble(scanner);

                    service.updateCourseFee(id6, course6, fee6);
                    break;

                case 7:
                    System.out.print("Student ID: ");
                    int id7 = readInt(scanner);

                    System.out.print("Course Name: ");
                    String course7 = readNonBlank(scanner, "Course Name");

                    service.cancelCourseRegistration(id7, course7);
                    break;

                case 8:
                    System.out.print("Student ID: ");
                    service.deleteStudentCompletely(readInt(scanner));
                    break;

                case 9:
                    System.out.print("Minimum Fee: ");
                    service.generateHighPayingStudentsReport(readDouble(scanner));
                    break;

                case 10:
                    service.generateCourseWiseCountReport();
                    break;

                case 11:
                    System.out.println("Exiting...");
                    return;

                default:
                    System.out.println("Invalid choice.");
                    break;
            }
        }
    }

    private static int readInt(Scanner scanner) {
        while (!scanner.hasNextInt()) {
            System.out.print("Enter a valid integer: ");
            scanner.next();
        }
        int value = scanner.nextInt();
        scanner.nextLine();
        return value;
    }

    private static double readDouble(Scanner scanner) {
        while (!scanner.hasNextDouble()) {
            System.out.print("Enter a valid number: ");
            scanner.next();
        }
        double value = scanner.nextDouble();
        scanner.nextLine();
        return value;
    }

    private static String readNonBlank(Scanner scanner, String fieldName) {
        while (true) {
            String value = scanner.nextLine().trim();
            if (!value.isEmpty()) {
                return value;
            }
            System.out.print(fieldName + " cannot be empty or blank. Please enter again: ");
        }
    }

    private static String readValidName(Scanner scanner, String fieldName) {
        while (true) {
            String name = readNonBlank(scanner, fieldName);
            if (NAME_PATTERN.matcher(name).matches()) {
                return name;
            }
            System.out.print(fieldName + " must contain letters and spaces only (no numbers/symbols). Please enter again: ");
        }
    }
}

package com.project.app.app;

import com.project.app.model.StudentModel;
