        String sql =
                "SELECT s.id, s.name, c.course_name, r.fees_paid " +
                        "FROM student s JOIN registration r ON s.id = r.student_id " +
                        "JOIN course c ON r.course_id = c.course_id " +
                        "WHERE r.fees_paid > ? ORDER BY r.fees_paid DESC";
        List<String> out = new ArrayList<>();
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setDouble(1, minFee);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    out.add(String.format("ID=%d, Name=%s, Course=%s, Paid=%.2f",
                            rs.getInt("id"), rs.getString("name"),
                            rs.getString("course_name"), rs.getDouble("fees_paid")));
                }
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
        return out;
    }

    public List<String> courseWiseCount(Connection connection) {
        String sql = "SELECT c.course_name, COUNT(*) AS cnt FROM registration r JOIN course c ON r.course_id = c.course_id GROUP BY c.course_name ORDER BY c.course_name";
        List<String> out = new ArrayList<>();
        try (PreparedStatement ps = connection.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                out.add(rs.getString("course_name") + " -> " + rs.getInt("cnt"));
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
        return out;
    }

    public List<CourseModel> fetchAllCourses(Connection connection) {
        String sql = "SELECT course_id, course_name FROM course ORDER BY course_name";
        List<CourseModel> out = new ArrayList<>();
        try (PreparedStatement ps = connection.prepareStatement(sql);
             ResultSet rs = ps.executeQuery()) {
            while (rs.next()) {
                out.add(new CourseModel(rs.getInt("course_id"), rs.getString("course_name")));
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
        return out;
    }
}

package com.project.app.dao;

import com.project.app.model.StudentModel;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Optional;

public class StudentDataAccessObject {

    public boolean insertStudent(Connection connection, StudentModel student) throws SQLException {
        // Resolve or create branch_id from branch name
        int branchId = getOrCreateBranchId(connection, student.getStudentBranch());
        String sql = "INSERT INTO student (id, name, age, branch_id) VALUES (?, ?, ?, ?)";
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setInt(1, student.getStudentId());
            ps.setString(2, student.getStudentName());
            ps.setInt(3, student.getStudentAge());
            ps.setInt(4, branchId);
            return ps.executeUpdate() == 1;
        }
    }

    public boolean isStudentExists(Connection connection, int studentId) throws SQLException {
        String sql = "SELECT 1 FROM student WHERE id = ?";
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setInt(1, studentId);
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next();
            }
        }
    }

    public Optional<StudentModel> findStudentById(Connection connection, int studentId) throws SQLException {
        String sql = "SELECT s.id, s.name, s.age, b.branch_name AS branch FROM student s LEFT JOIN branch b ON s.branch_id = b.branch_id WHERE s.id = ?";
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setInt(1, studentId);
            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) return Optional.empty();
                return Optional.of(new StudentModel(
                        rs.getInt("id"),
                        rs.getString("name"),
                        rs.getInt("age"),
                        rs.getString("branch")
                ));
            }
        }
    }

    public int updateStudentDetails(Connection connection, int studentId, String studentName, String studentBranch) throws SQLException {
        int branchId = getOrCreateBranchId(connection, studentBranch);
        String sql = "UPDATE student SET name = ?, branch_id = ? WHERE id = ?";
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setString(1, studentName);
            ps.setInt(2, branchId);
            ps.setInt(3, studentId);
            return ps.executeUpdate();
        }
    }

    public int deleteStudentById(Connection connection, int studentId) throws SQLException {
        String sql = "DELETE FROM student WHERE id = ?";
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setInt(1, studentId);
            return ps.executeUpdate();
        }
    }

    private int getOrCreateBranchId(Connection connection, String branchName) throws SQLException {
        if (branchName == null) branchName = "";
        String selectSql = "SELECT branch_id FROM branch WHERE branch_name = ?";
        try (PreparedStatement ps = connection.prepareStatement(selectSql)) {
            ps.setString(1, branchName);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) return rs.getInt("branch_id");
            }
        }

        String insertSql = "INSERT INTO branch (branch_name) VALUES (?)";
        try (PreparedStatement ps = connection.prepareStatement(insertSql, PreparedStatement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, branchName);
            ps.executeUpdate();
            try (ResultSet rs = ps.getGeneratedKeys()) {
                if (rs.next()) return rs.getInt(1);
            }
        }
        // Fallback
        throw new SQLException("Unable to resolve or create branch id for: " + branchName);
    }
}

package com.project.app.dao;

import com.project.app.exceptions.DataAccessException;
import com.project.app.exceptions.DuplicateEntityException;
import com.project.app.model.StudentModel;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.SQLIntegrityConstraintViolationException;
import java.util.Optional;

public class StudentDataAccessObject {

    public boolean insertStudent(Connection connection, StudentModel student) {
        try {
            // Resolve or create branch_id from branch name
            int branchId = getOrCreateBranchId(connection, student.getStudentBranch());
            String sql = "INSERT INTO student (id, name, age, branch_id) VALUES (?, ?, ?, ?)";
            try (PreparedStatement ps = connection.prepareStatement(sql)) {
                ps.setInt(1, student.getStudentId());
                ps.setString(2, student.getStudentName());
                ps.setInt(3, student.getStudentAge());
                ps.setInt(4, branchId);
                return ps.executeUpdate() == 1;
            }
        } catch (SQLIntegrityConstraintViolationException ex) {
            throw new DuplicateEntityException("Student with ID already exists: " + student.getStudentId(), ex);
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
    }

    public boolean isStudentExists(Connection connection, int studentId) {
        try {
            String sql = "SELECT 1 FROM student WHERE id = ?";
            try (PreparedStatement ps = connection.prepareStatement(sql)) {
                ps.setInt(1, studentId);
                try (ResultSet rs = ps.executeQuery()) {
                    return rs.next();
                }
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
    }

    public Optional<StudentModel> findStudentById(Connection connection, int studentId) {
        try {
            String sql = "SELECT s.id, s.name, s.age, b.branch_name AS branch FROM student s LEFT JOIN branch b ON s.branch_id = b.branch_id WHERE s.id = ?";
            try (PreparedStatement ps = connection.prepareStatement(sql)) {
                ps.setInt(1, studentId);
                try (ResultSet rs = ps.executeQuery()) {
                    if (!rs.next()) return Optional.empty();
                    return Optional.of(new StudentModel(
                            rs.getInt("id"),
                            rs.getString("name"),
                            rs.getInt("age"),
                            rs.getString("branch")
                    ));
                }
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
    }

    public int updateStudentDetails(Connection connection, int studentId, String studentName, String studentBranch) {
        try {
            int branchId = getOrCreateBranchId(connection, studentBranch);
            String sql = "UPDATE student SET name = ?, branch_id = ? WHERE id = ?";
            try (PreparedStatement ps = connection.prepareStatement(sql)) {
                ps.setString(1, studentName);
                ps.setInt(2, branchId);
                ps.setInt(3, studentId);
                return ps.executeUpdate();
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
    }

    public int deleteStudentById(Connection connection, int studentId) {
        try {
            String sql = "DELETE FROM student WHERE id = ?";
            try (PreparedStatement ps = connection.prepareStatement(sql)) {
                ps.setInt(1, studentId);
                return ps.executeUpdate();
            }
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
    }

    private int getOrCreateBranchId(Connection connection, String branchName) {
        try {
            if (branchName == null) branchName = "";
            String selectSql = "SELECT branch_id FROM branch WHERE branch_name = ?";
            try (PreparedStatement ps = connection.prepareStatement(selectSql)) {
                ps.setString(1, branchName);
                try (ResultSet rs = ps.executeQuery()) {
                    if (rs.next()) return rs.getInt("branch_id");
                }
            }

            String insertSql = "INSERT INTO branch (branch_name) VALUES (?)";
            try (PreparedStatement ps = connection.prepareStatement(insertSql, PreparedStatement.RETURN_GENERATED_KEYS)) {
                ps.setString(1, branchName);
                ps.executeUpdate();
                try (ResultSet rs = ps.getGeneratedKeys()) {
                    if (rs.next()) return rs.getInt(1);
                }
            }
            // Fallback
            throw new DataAccessException("Unable to resolve or create branch id for: " + branchName);
        } catch (SQLIntegrityConstraintViolationException ex) {
            throw new DuplicateEntityException("Branch already exists: " + branchName, ex);
        } catch (SQLException ex) {
            throw new DataAccessException(ex);
        }
    }
}

